mapper.select:
SELECT
COUNT(*) as totalUsers,
SUM(CASE WHEN user_type = '00' THEN 1 ELSE 0 END) as policeCount,
SUM(CASE WHEN user_type = '11' THEN 1 ELSE 0 END) as releasedCount,
SUM(CASE WHEN user_type = '22' THEN 1 ELSE 0 END) as rehabCount,
SUM(CASE WHEN user_type = '33' THEN 1 ELSE 0 END) as otherCount
FROM sys_user u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.department = #{department}

SELECT CASE WHEN user_type = '00' THEN '警官' WHEN user_type = '11' THEN '出所人员' WHEN user_type = '22' THEN '社康社戒人员' WHEN user_type = '33' THEN '游客及其他' ELSE '其他' END as name, COUNT(*) as value FROM sys_user u WHERE u.del_flag = '0'
AND DATE(u.create_time) >= #{startDate}
AND DATE(u.create_time) <= #{endDate}
AND u.user_type = #{userType}
AND u.department = #{department}
GROUP BY user_type ORDER BY value DESC

SELECT
DATE_FORMAT(create_time, '%Y-%m-%d') as date,
COUNT(*) as count
FROM sys_user u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.department = #{department}

GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY date ASC

SELECT
CONCAT('第', WEEK(create_time, 1), '周') as week,
COUNT(*) as count
FROM sys_user u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.department = #{department}

GROUP BY YEARWEEK(create_time, 1)
ORDER BY YEARWEEK(create_time, 1) ASC

SELECT
DATE_FORMAT(create_time, '%Y年%m月') as month,
COUNT(*) as count
FROM sys_user u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.department = #{department}

GROUP BY DATE_FORMAT(create_time, '%Y-%m')
ORDER BY DATE_FORMAT(create_time, '%Y-%m') ASC

SELECT
DATE_FORMAT(login_date, '%Y-%m-%d') as date,
COUNT(DISTINCT user_id) as count
FROM sys_login_log
WHERE status = '0'  -- 登录成功

    AND DATE(login_date) >= #{startDate}


    AND DATE(login_date) <= #{endDate}


    AND user_type = #{userType}


    AND department = #{department}

GROUP BY DATE_FORMAT(login_date, '%Y-%m-%d')
ORDER BY date ASC
